{"script": "w = env.run(["which", "cargo"], check = False)
p = w.stdout.strip()
info = {"which": w.stdout, "code": w.code}
if p:
    ls = env.run(["ls", "-l", p], check = False)
    info["ls"] = ls.stdout
    head = env.run(["head", "-c", "1200", p], check = False)
    info["head"] = head.stdout
    info["file"] = env.run(["file", p], check = False).stdout
result(info)"}

